select make_interval(secs => 5) as five, make_interval(days => n) as days, substring(kind from 1 for 3) as head, substring(kind, n) as tail, substr(kind, 2) as rest, substring(kind from 'a+') as matched, substring(kind similar 'a%' escape '#') as similar, position('a' in kind) as at_a, format('%s-%s', kind, id) as formatted, format('%s', note) as with_null, format(note, kind) as null_format from events
